export enum LeaveType {
  annual = 'annual',
  sick = 'sick',
  emergency = 'emergency',
}

export enum LeaveStatus {
  draft = 'draft',
  submitted = 'submitted',
  approved = 'approved',
  rejected = 'rejected',
  cancelled = 'cancelled',
}

export enum EmploymentStatus {
  active = 'active',
  inactive = 'inactive',
  terminated = 'terminated',
}

export enum BalanceStatus {
  active = 'active',
  exhausted = 'exhausted',
}

export enum NotificationType {
  leave_submitted = 'leave_submitted',
  leave_approved = 'leave_approved',
  leave_rejected = 'leave_rejected',
  leave_cancelled = 'leave_cancelled',
}

export enum NotificationStatus {
  pending = 'pending',
  sent = 'sent',
  read = 'read',
  archived = 'archived',
}
import { EmploymentStatus } from '../../shared/types';

export interface Employee {
  id: string;
  employeeNumber: string;
  firstName: string;
  lastName: string;
  email: string;
  managerId: string | null;
  department: string | null;
  hireDate: Date;
  terminationDate: Date | null;
  employmentStatus: EmploymentStatus;
  createdAt: Date;
  updatedAt: Date;
  deletedAt: Date | null;
}

export interface IEmployeeRepository {
  findById(id: string): Promise<Employee | null>;
  findByEmployeeNumber(employeeNumber: string): Promise<Employee | null>;
  findAll(): Promise<Employee[]>;
  create(employee: Omit<Employee, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>): Promise<Employee>;
  update(id: string, data: Partial<Employee>): Promise<Employee | null>;
  softDelete(id: string): Promise<void>;
}
